businessControlRouter.get('/applications',async(req,res,next)=>{try{if(!await context(req,res,'applications:approve',false,'INTERNAL'))return;const result=await pool.query(`SELECT o.id,o.legal_name AS "legalName",o.trading_name AS "tradingName",o.status,o.registration_country AS "registrationCountry",p.industry,p.expected_monthly_volume::text AS "expectedMonthlyVolume",p.expected_monthly_transactions::text AS "expectedMonthlyTransactions",p.updated_at AS "updatedAt",f.provisioning_state AS "provisioningState",f.vfd_account_number AS "vfdAccountNumber",f.smart_account_address AS "smartAccountAddress" FROM organizations o JOIN business_compliance_profiles p ON p.organization_id=o.id LEFT JOIN business_financial_accounts f ON f.organization_id=o.id WHERE o.type='BUSINESS' AND o.status IN ('COMPLIANCE_SUBMITTED','UNDER_REVIEW','ADDITIONAL_INFORMATION_REQUIRED','APPROVED','ACTIVE') ORDER BY p.updated_at DESC`);res.json({applications:result.rows});}catch(e){next(e);}});
