businessControlRouter.post('/terminal-requests/:id/approve',async(req,res,next)=>{try{const current=await context(req,res,'accounts:activate',true,'INTERNAL');if(!current)return;const db=await pool.connect();try{await db.query('BEGIN');const request=await db.query(`SELECT * FROM terminal_requests WHERE id=$1 FOR UPDATE`,[req.params.id]);const row=request.rows[0];if(!row||!['SUBMITTED','UNDER_REVIEW'].includes(row.status)){res.status(409).json({error:'This terminal request cannot be approved.',code:'INVALID_STATE'});await db.query('ROLLBACK');return;}const org=await db.query(`SELECT status FROM organizations WHERE id=$1`,[row.organization_id]);if(org.rows[0]?.status!=='ACTIVE'){res.status(409).json({error:'Activate the business before approving terminals.',code:'BUSINESS_NOT_ACTIVE'});await db.query('ROLLBACK');return;}const terminals:Array<{terminalId:string;type:string;activationCode:string;expiresAt:string}>=[];for(const[type,count]of[['HARDWARE',row.hardware_quantity],['SOFTWARE',row.software_device_count]] as const){for(let i=0;i<Number(count);i++){const terminalId=randomUUID();await db.query(`INSERT INTO merchant_terminals(id,organization_id,label,terminal_type,status) VALUES($1,$2,$3,$4,'PENDING_ACTIVATION')`,[terminalId,row.organization_id,`${row.location_name} ${type.toLowerCase()} ${i+1}`,type]);const activation=await issueTerminalActivation(terminalId,db);terminals.push({terminalId,type,activationCode:activation.code,expiresAt:activation.expiresAt});}}await db.query(`UPDATE terminal_requests SET status='APPROVED',reviewed_by=$2,reviewed_at=NOW(),updated_at=NOW() WHERE id=$1`,[row.id,current.session.user.id]);await db.query('COMMIT');res.json({id:row.id,status:'APPROVED',terminals});}catch(e){await db.query('ROLLBACK');throw e;}finally{db.release();}}catch(e){next(e);}});

async function listManagedTerminals(organizationId?:string){const result=await pool.query(`SELECT t.id,t.label,t.terminal_type AS "terminalType",t.status,t.activated_at AS "activatedAt",t.last_seen_at AS "lastSeenAt",t.created_at AS "createdAt",o.legal_name AS "businessName",o.id AS "organizationId",(SELECT COUNT(*)::text FROM terminal_payments p WHERE p.terminal_id=t.id) AS "paymentCount" FROM merchant_terminals t JOIN organizations o ON o.id=t.organization_id WHERE ($1::uuid IS NULL OR t.organization_id=$1::uuid) ORDER BY t.created_at DESC`,[organizationId??null]);return result.rows;}
