businessControlRouter.post('/terminals/:id/:action',async(req,res,next)=>{try{const current=await context(req,res,'terminals:manage',true,'INTERNAL');if(!current)return;const action=String(req.params.action);if(!['suspend','resume','revoke','reissue-activation'].includes(action)){res.status(404).json({error:'Terminal action not found.',code:'NOT_FOUND'});return;}const parsed=terminalAction.safeParse(req.body);if(!parsed.success){res.status(400).json({error:'Add a short reason for this action.',code:'VALIDATION_ERROR'});return;}const db=await pool.connect();try{await db.query('BEGIN');const result=await db.query(`SELECT * FROM merchant_terminals WHERE id=$1 FOR UPDATE`,[req.params.id]);const row=result.rows[0];if(!row){res.status(404).json({error:'Terminal not found.',code:'NOT_FOUND'});await db.query('ROLLBACK');return;}if(action==='reissue-activation'){if(row.status!=='PENDING_ACTIVATION'){res.status(409).json({error:'Only terminals waiting for activation can receive a new code.',code:'INVALID_STATE'});await db.query('ROLLBACK');return;}await db.query(`UPDATE terminal_activation_codes SET consumed_at=COALESCE(consumed_at,NOW()) WHERE terminal_id=$1 AND consumed_at IS NULL`,[row.id]);const activation=await issueTerminalActivation(row.id,db);await db.query(`INSERT INTO terminal_operational_events(terminal_id,event_type,actor_type,actor_reference,reason) VALUES($1,'ACTIVATION_REISSUED','OPERATOR',$2,$3)`,[row.id,current.session.user.id,parsed.data.reason]);await db.query('COMMIT');res.json({terminalId:row.id,activationCode:activation.code,expiresAt:activation.expiresAt});return;}const next=action==='suspend'?'SUSPENDED':action==='resume'?'ACTIVE':'REVOKED';const allowed=(action==='suspend'&&row.status==='ACTIVE')||(action==='resume'&&row.status==='SUSPENDED')||(action==='revoke'&&row.status!=='REVOKED');if(!allowed){res.status(409).json({error:'This terminal action is not available from its current state.',code:'INVALID_STATE'});await db.query('ROLLBACK');return;}await db.query(`UPDATE merchant_terminals SET status=$2,suspended_at=CASE WHEN $2='SUSPENDED' THEN NOW() ELSE suspended_at END,revoked_at=CASE WHEN $2='REVOKED' THEN NOW() ELSE revoked_at END,secret_hash=CASE WHEN $2='REVOKED' THEN NULL ELSE secret_hash END,updated_at=NOW() WHERE id=$1`,[row.id,next]);await db.query(`INSERT INTO terminal_operational_events(terminal_id,event_type,actor_type,actor_reference,reason,metadata) VALUES($1,$2,'OPERATOR',$3,$4,$5)`,[row.id,`TERMINAL_${next}`,current.session.user.id,parsed.data.reason,{fromStatus:row.status,toStatus:next}]);await db.query('COMMIT');res.json({terminalId:row.id,status:next});}catch(error){await db.query('ROLLBACK');throw error;}finally{db.release();}}catch(e){next(e);}});

businessControlRouter.get('/payments',async(req,res,next)=>{try{if(!await context(req,res,'payments:read',false,'INTERNAL'))return;const filters=paymentFilters(req.query);res.json({payments:await terminalPayments(filters)});}catch(e){next(e);}});
businessControlRouter.get('/payments/:id',async(req,res,next)=>{try{if(!await context(req,res,'payments:read',false,'INTERNAL'))return;const detail=await terminalPaymentDetail(String(req.params.id));if(!detail){res.status(404).json({error:'Payment not found.',code:'NOT_FOUND'});return;}res.json(detail);}catch(e){next(e);}});
businessControlRouter.post('/payments/:id/reconcile',async(req,res,next)=>{try{const current=await context(req,res,'accounts:activate',true,'INTERNAL');if(!current)return;const result=await reconcileTerminalPaymentNow(String(req.params.id));await pool.query(`INSERT INTO terminal_payment_events(payment_id,event_type,from_state,to_state,actor_type,actor_reference,metadata) SELECT id,'OPERATOR_RECONCILIATION',state,state,'OPERATOR',$2,$3 FROM terminal_payments WHERE id=$1`,[req.params.id,current.session.user.id,{providerReference:result.providerReference}]);res.json(result);}catch(e){next(e);}});

businessControlRouter.get('/profiles/:identifier',async(req,res,next)=>{try{if(!await context(req,res,'compliance:read',false,'INTERNAL'))return;const parsed=z.string().min(1).max(100).regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/i).safeParse(req.params.identifier);if(!parsed.success){res.status(400).json({error:'Choose a valid business.',code:'VALIDATION_ERROR'});return;}const detail=await registeredBusinessById(parsed.data);if(!detail){res.status(404).json({error:'This business could not be found.',code:'BUSINESS_NOT_FOUND'});return;}res.json(detail);}catch(error){next(error);}});

const businessReason=z.object({reason:z.string().trim().min(3).max(1000)});
for(const action of ['deactivate','reactivate'] as const)businessControlRouter.post(`/:id/${action}`,async(req,res,next)=>{try{const current=await context(req,res,action==='deactivate'?'accounts:suspend':'accounts:activate',true,'INTERNAL');if(!current)return;const id=z.uuid().safeParse(req.params.id),parsed=businessReason.safeParse(req.body);if(!id.success||!parsed.success){res.status(400).json({error:'Choose a business and add a short reason.',code:'VALIDATION_ERROR'});return;}res.json(await changeBusinessActivation(id.data,current.session.user.id,action,parsed.data.reason));}catch(error){next(error);}});
businessControlRouter.post('/:id/information-requests',async(req,res,next)=>{try{const current=await context(req,res,'compliance:review',true,'INTERNAL');if(!current)return;const id=z.uuid().safeParse(req.params.id),parsed=z.object({requestId:z.uuid(),note:z.string().trim().min(3).max(2000)}).safeParse(req.body);if(!id.success||!parsed.success){res.status(400).json({error:'Add the information this business needs to provide.',code:'VALIDATION_ERROR'});return;}const result=await requestBusinessInformation(id.data,current.session.user.id,parsed.data.requestId,parsed.data.note);res.status(result.created?201:200).json(result);}catch(error){next(error);}});
businessControlRouter.post('/:id/information-requests/:requestId/resolve',async(req,res,next)=>{try{const current=await context(req,res,'compliance:review',true,'INTERNAL');if(!current)return;const id=z.uuid().safeParse(req.params.id),requestId=z.uuid().safeParse(req.params.requestId),parsed=z.object({note:z.string().trim().max(1000).default('')}).safeParse(req.body);if(!id.success||!requestId.success||!parsed.success){res.status(400).json({error:'Choose a valid information request.',code:'VALIDATION_ERROR'});return;}res.json(await resolveBusinessInformation(id.data,requestId.data,current.session.user.id,parsed.data.note));}catch(error){next(error);}});
businessRouter.get('/information-requests',async(req,res,next)=>{try{const current=await context(req,res,'compliance:read',false,'BUSINESS');if(!current)return;res.json({requests:await businessInformationRequests(current.organization.id)});}catch(error){next(error);}});
businessRouter.post('/information-requests/:id/respond',async(req,res,next)=>{try{const current=await context(req,res,'compliance:submit',true,'BUSINESS');if(!current)return;const id=z.uuid().safeParse(req.params.id),parsed=z.object({response:z.string().trim().min(3).max(4000)}).safeParse(req.body);if(!id.success||!parsed.success){res.status(400).json({error:'Add your response before submitting.',code:'VALIDATION_ERROR'});return;}res.json(await respondToBusinessInformation(current.organization.id,id.data,current.session.user.id,parsed.data.response));}catch(error){next(error);}});

for(const router of[businessRouter,businessControlRouter])router.use((error:unknown,_req:Request,res:Response,_next:unknown)=>{
 const message=error instanceof Error?error.message:'Unknown error';console.error('[business] request failed',{message,...(error instanceof VfdError?{provider:'VFD',kind:error.kind,code:error.code}:{})});
 if(error instanceof TerminalError){res.status(error.status).json({error:error.message,code:error.code});return;}
 if(error instanceof BusinessManagementError){res.status(error.status).json({error:error.message,code:error.code});return;}
 if(error instanceof MartError){res.status(error.status).json({error:error.message,code:error.code});return;}
 const databaseError=error as {code?:string;constraint?:string};if(databaseError.code==='23505'){res.status(409).json({error:'That bank or settlement account is already linked to another business.',code:'ACCOUNT_ALREADY_LINKED'});return;}
 if(error instanceof VfdError){const status=error.kind==='rejected'?422:503;const publicError=publicCorporateVfdError(error);const unavailableMessage=error.code==='VFD_NETWORK'?'VFD did not respond in time. Wait a moment and retry; Oynk will recover the existing account if VFD already created it.':'Business banking is temporarily unavailable.';res.status(status).json({error:error.kind==='rejected'?publicError.message:unavailableMessage,code:error.kind==='rejected'?publicError.code:error.code});return;}
 if(/wallet request|connected wallet|signed wallet|Stellar account not found|USDC was submitted|enable USDC|Invalid smart-account session|Sign in again/i.test(message)){res.status(409).json({error:message,code:'ACCOUNT_SETUP_FAILED'});return;}
 res.status(503).json({error:'The business service could not complete this request.',code:'BUSINESS_SERVICE_UNAVAILABLE'});
});
